# Zak McKracken (V2 DOS, zakkor Korean patch). One map, one face in every render_target
# (1 bpp, hard-edged). The pairing selection (2026-10-15): SANGAM16.SVF, the 16 px san-1.0
# GAM.KOR jamo set (layout 844, ascent 14) with SAN.ENG for ASCII, shared with
# KQ4 (SAN10.TXT). It replaces the earlier two presets (a true colour
# 2 bpp gothic face and a clut8 pixel face).
# The game has one charset (cs0), 16x16 cells at scale 2 (the game's 8 px cell).
# Licence: see SAN10.TXT beside this file (san 1.0, MIT).
[map]
version=2

[render]
scale=2
blend=off

[text]
encoding=cp949

[fonts]
dlg=SANGAM16.SVF

[font]
missing=u+25a1
# ASCII from the SVF (never the game's internal font), stepped by the
# face's own widths
range.basic-latin=same
advance.basic-latin=font
# The baked SVF already sets the baseline the Hangul stands on: drop the game
# glyph's own offsets for Latin and punctuation, or ':' '.' sit low (Indy 4's credits).
origin.basic-latin=face
origin.general-punctuation=face

[font.0]
face=dlg

# The control range 0x01-0x1F holds only the game's own pictures, never text: the
# inventory scroll arrows (0x01-0x04) and the box pieces after them. No face has a
# glyph there. Everything else the translation parks on an odd byte code is real
# punctuation, drawn by the replacement font:
#   0x5e ellipsis ("10 초^", "Diabolically fun^wildly entertaining^"; the game's own
#     glyph is two rows of dots on the baseline)
#   0x60 double quote, opening and closing (the game's glyph at 0x60 is the same
#     picture as its 0x22)
# The '~' of the translation ("아~하!") is a tilde: the game's own 0x7e is a left arrow,
# which the face's tilde replaces. "Game A@@" in the save lines is the game's own bar,
# which is the game's 0x40 glyph, so it stays.
[glyphs]
0x01-0x1f = original
0x40 = original
0x5e = u+2026
0x60 = u+0022
